public List<List<Integer>> permute(int[] nums) {
    // Edge case: If the input array has only one element, return the array with that element
    if (nums.length == 1) {
        return Arrays.asList(nums);
    }

    // Initialize the result list
    List<List<Integer>> result = new ArrayList<>();

    // Iterate over all possible permutations of the input array
    for (int i = 0; i < nums.length; i++) {
        // Extract the current element and the remaining elements
        int current = nums[i];
        int[] remaining = Arrays.copyOfRange(nums, i + 1, nums.length);

        // Recursively permute the remaining elements
        List<List<Integer>> subPermutations = permute(remaining);

        // Add the current element to all possible permutations of the remaining elements
        for (List<Integer> subPermutation : subPermutations) {
            List<Integer> permutation = new ArrayList<>();
            permutation.add(current);
            permutation.addAll(subPermutation);
            result.add(permutation);
        }
    }

    return result;
}
