            return str1.length();
        }

        // Iterate over the rest of the strings and find the longest substring
        // that can be found in both the current string and its inverse
        for (int j = i + 1; j < strings.size(); j++) {
            String str2 = strings.get(j);

            // The longest common substring can be found by taking the
            // intersection of the two strings
            int minLength = Math.min(str1.length(), str2.length());
            int maxLength = 0;
            for (int k = 0; k < minLength; k++) {
                if (str1.charAt(k) == str2.charAt(k)) {
                    maxLength = k + 1;
                } else {
                    break;
                }
            }

            largestSubstring = Math.max(largestSubstring, maxLength);
        }
    }

    return largestSubstring;
