public static int countOilDeposits(char[][] grid) {
    // Check if the grid is empty or if there are any invalid characters in the grid
    if (grid.length == 0 || grid[0].length == 0) {
        return 0;
    }
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[i].length; j++) {
            if (grid[i][j] != '*' && grid[i][j] != '@') {
                throw new IllegalArgumentException("Invalid character in grid");
            }
        }
    }

    // Initialize a hash set to keep track of the oil deposits
    Set<String> deposits = new HashSet<>();

    // Iterate through the grid and mark the oil deposits
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[i].length; j++) {
            if (grid[i][j] == '@') {
                deposits.add(getDepositKey(grid, i, j));
            }
        }
    }

    // Return the number of unique oil deposits
    return deposits.size();
}

public static String getDepositKey(char[][] grid, int i, int j) {
    // Calculate the key for the current deposit based on the row and column index
    StringBuilder key = new StringBuilder();
    for (int row = i - 1; row <= i + 1; row++) {
        for (int col = j - 1; col <= j + 1; col++) {
            if (row >= 0 && row < grid.length && col >= 0 && col < grid[row].length) {
                if (grid[row][col] == '@') {
                    key.append(getNeighboringDepositKey(grid, row, col));
                }
            }
        }
    }
    return key.toString();
}

public static String getNeighboringDepositKey(char[][] grid, int i, int j) {
    // Calculate the key for the neighboring deposit based on the row and column index
    StringBuilder key = new StringBuilder();
    for (int row = i - 1; row <= i + 1; row++) {
        for (int col = j - 1; col <= j + 1; col++) {
            if (row >= 0 && row < grid.length && col >= 0 && col < grid[row].length) {
                if (grid[row][col] == '@') {
                    key.append(' ');
                } else {
                    key.append('_');
                }
            }
        }
    }
    return key.toString();
}

