public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Create a graph from the edge list
    Graph graph = new Graph(n);
    for (int[] edge : edges) {
        graph.addEdge(edge[0], edge[1]);
    }

    // Perform BFS to find the shortest path from the start node to all other nodes
    Queue<Integer> queue = new LinkedList<>();
    boolean[] visited = new boolean[n];
    int[] distance = new int[n];
    Arrays.fill(distance, -1);
    queue.offer(0);
    visited[0] = true;
    distance[0] = 0;

    while (!queue.isEmpty()) {
        int node = queue.poll();
        for (int neighbor : graph.getNeighbors(node)) {
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                distance[neighbor] = distance[node] + 1;
                queue.offer(neighbor);
            }
        }
    }

    // Find the minimum time required to collect all apples
    int time = 0;
    for (int i = 0; i < n; i++) {
        if (hasApple[i]) {
            time = Math.max(time, distance[i]);
        }
    }
    return time;
}

