public int[][] diagonalDifference(int[][] mat) {
    // Initialize an array to store the absolute differences of the diagonals
    int[][] diagonals = new int[mat.length][2];

    // Calculate the absolute difference between the main diagonal and the anti-diagonal
    int mainDiagonalSum = 0;
    int antiDiagonalSum = 0;
    for (int i = 0; i < mat.length; i++) {
        mainDiagonalSum += mat[i][i];
        antiDiagonalSum += mat[i][mat.length - i - 1];
    }

    // Calculate the absolute difference between the main diagonal and the anti-diagonal
    int mainDiagonalDiff = Math.abs(mainDiagonalSum);
    int antiDiagonalDiff = Math.abs(antiDiagonalSum);

    // Add the absolute differences of the main and anti-diagonals to the output array
    diagonals[0][0] = mainDiagonalDiff;
    diagonals[0][1] = antiDiagonalDiff;

    // Return the output array
    return diagonals;
}
