public int minInsertions(String s) {
    // Initialize variables
    int openParens = 0;
    int insertions = 0;

    // Iterate through the string
    for (int i = 0; i < s.length(); i++) {
        char current = s.charAt(i);

        // If the current character is a '(', increment the number of open parentheses
        if (current == '(') {
            openParens++;
        }
        // If the current character is a ')', decrement the number of open parentheses
        else if (current == ')') {
            openParens--;
        }

        // If the number of open parentheses is negative, it means there are more closing brackets than opening brackets
        if (openParens < 0) {
            // Add the number of opening parentheses to the number of insertions
            insertions += openParens;
            // Reset the number of open parentheses to 0
            openParens = 0;
        }
    }

    // Return the number of insertions
    return insertions;
}
```
