public int minInsertions(String s) {
    int left = 0;
    int right = 0;

    // Iterate through the string 's' and count the number of left and right brackets
    for (char c : s.toCharArray()) {
        if (c == '(') {
            left++;
        } else if (c == ')') {
            right++;
        }
    }

    // If the number of left and right brackets is already balanced, return 0
    if (left == right) {
        return 0;
    }

    // Calculate the minimum number of insertions required to make the string balanced
    int minInsertions = Math.abs(left - right);

    // If the number of insertions is odd, add an extra ')' to make it even
    if (minInsertions % 2 != 0) {
        minInsertions++;
    }

    return minInsertions;
}
