public int minOperations(int n) {
  int[] arr = new int[n];
  for (int i = 0; i < n; i++) {
    arr[i] = (2 * i) + 1;
  }

  int minOperations = 0;
  while (!allEqual(arr)) {
    // Find two indices with different values
    int x = -1;
    int y = -1;
    for (int i = 0; i < n; i++) {
      if (arr[i] != arr[0]) {
        x = i;
        break;
      }
    }
    for (int i = 1; i < n; i++) {
      if (arr[i] != arr[0]) {
        y = i;
        break;
      }
    }

    // Subtract 1 from x and add 1 to y
    arr[x] -= 1;
    arr[y] += 1;
    minOperations++;
  }

  return minOperations;
}

