public int findMinFibonacciNumbers(int k) {
    // edge case: k is 1 or less, return 1
    if (k <= 1) {
        return 1;
    }

    // edge case: k is greater than the first two Fibonacci numbers, return 2
    if (k > 1 && k <= 2) {
        return 2;
    }

    // initialize variables
    int first = 1;
    int second = 1;
    int sum = first + second;
    int count = 2;

    // loop until the sum is equal to k
    while (sum != k) {
        // calculate the next Fibonacci number
        int next = first + second;

        // increment the count if the sum is greater than k
        if (sum > k) {
            count++;
        }

        // set the first Fibonacci number to the second Fibonacci number
        first = second;

        // set the second Fibonacci number to the next Fibonacci number
        second = next;

        // update the sum
        sum = first + second;
    }

    // return the count
    return count;
}

