	int maxUniques = 0;
	for (int i = 0; i < s.length(); i++) {
		// Find the rightmost character in the substring
		int rightMost = i;
		while (rightMost < s.length() && s.charAt(rightMost) == s.charAt(i)) {
			rightMost++;
