public static int calculateEnergy(String s) {
    // Initialize the longest non-empty substring with 0 energy
    int longestSubstring = 0;
    int currentSubstring = 0;
    int currentCharEnergy = -1;

    for (int i = 0; i < s.length(); i++) {
        // Get the current character and its energy
        char c = s.charAt(i);
        int charEnergy = (c == currentCharEnergy) ? 1 : 0;

        // Update the current substring energy and its length
        currentSubstring += charEnergy;
        if (currentSubstring > longestSubstring) {
            longestSubstring = currentSubstring;
        }

        // Update the current character energy and reset the substring energy if necessary
        currentCharEnergy = c;
        if (charEnergy == 0) {
            currentSubstring = 0;
        }
    }

    // Return the longest non-empty substring energy
    return longestSubstring;
}

