public static int minPerfectSquareSum(int n) {
    // Edge case: when n is 0, there is only 1 perfect square number (0), so the minimum is 1
    if (n == 0) {
        return 1;
    }

    // Initialize the minimum number of perfect square numbers to 2 (i.e., 1 + 1)
    int minSquares = 2;

    // Loop through all perfect square numbers from 1 to n
    for (int i = 1; i <= n; i++) {
        // If the sum of the current perfect square number and the previous perfect square number is greater than or equal to n,
        // then the current perfect square number is not the smallest one
        if (i * i + (i - 1) * (i - 1) >= n) {
            break;
        }

        // Increment the minimum number of perfect square numbers by 1
        minSquares++;
    }

    return minSquares;
}

