    Set<Integer> perfectSquares = new HashSet<>();
    for (int i = 1; i <= Math.sqrt(n); i++) {
        perfectSquares.add(i * i);
    }

    // Return the minimum number of perfect square numbers
    return perfectSquares.size();
}

